window.kbPageData["views/entry/k-a52fff3bbf608741"] = {"key":"entry/k-a52fff3bbf608741","state":{"route":"entry/k-a52fff3bbf608741"},"node":{"id":"k-a52fff3bbf608741","mode":"k","title":"品牌延伸引发的消费者心理冲突","type":"原理与机制","domain":"经济","reading":"","intro":"","priority":100,"aliases":["品牌延伸引发消费者心理冲突的条件"],"qs":["国考 2024 行政执法 行测#83"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"按题干定义，知名品牌用于与原产品不同类型的产品时，如果新品与原产品相对立或容易引起反感，消费者可能因原有品牌印象与新品用途产生矛盾，进而只购买其中一类或两类都不买，影响原有品牌形象。","review":{"definition":"按题干定义，知名品牌用于与原产品不同类型的产品时，如果新品与原产品相对立或容易引起反感，消费者可能因原有品牌印象与新品用途产生矛盾，进而只购买其中一类或两类都不买，影响原有品牌形象。","explanation":"D项中，消费者原先喜爱的是厨卫清洁品牌，后来却要接受同一品牌推出的可饮用产品。清洁用品与饮料的用途形成反差，消费者「一时难以接受」，最直接体现题干所说的心理冲突。B项写的是奢侈手提包品牌推出百元包后，部分消费者放弃该品牌，题面只交代了他们的选择，未明确呈现他们对两类产品的矛盾感受。","references":[],"evidence":"如果品牌延伸到一个与原产品相对立或易引起消费者反感的产品上，就会对消费者造成心理冲突。","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2024 行政执法 行测#83":{"paper":"国考 2024 行政执法 行测","n":83,"mod":"判断推理","src":["dfddc59dc6e7d9da5d71.pdf",18],"asrc":["6493f3a6a55c38431852.pdf",26],"card":"d4e37416deb015db6bde7187","links":[{"id":"k-a52fff3bbf608741","role":"直接考查","why":"产品之间的对立和消费者的心理反应共同限定了题目考查的品牌延伸后果。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-a52fff3bbf608741":[["国考 2024 行政执法 行测#83"]]}};
